public:
    vector<ll> parent;

    UnionFind(ll n) {
        parent.resize(n);
        for (ll i = 0; i < n; ++i) parent[i] = i;
    }

    ll find_set(ll a) {
        if (parent[a] == a) return a;
        parent[a] = find_set(parent[a]);
        return parent[a];
    }

    void union_sets(ll a, ll b) {
        a = find_set(a);
        b = find_set(b);
