import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class UnionFind {
        long[] parent;

        public UnionFind(int n) {
            parent = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public long findSet(long a) {
            if (parent[(int)a] == a) {
                return a;
            }
            parent[(int)a] = findSet(parent[(int)a]);
            return parent[(int)a];
        }

        public void unionSets(long a, long b) {
            a = findSet(a);
            b = findSet(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int)b] = a;
            }
        }
    }

    static long countCyclesInGraph(long p, long k) {
        UnionFind uf = new UnionFind((int)p);
        for (long i = 1; i < p; ++i) {
            long target = (k * i) % p;
            uf.unionSets(i, target);
        }
        boolean[] visited = new boolean[(int)p];
        long cycleCount = 0;
        for (long i = 1; i < p; ++i) {
            long root = uf.findSet(i);
            if (!visited[(int)root]) {
                visited[(int)root] = true;
                ++cycleCount;
            }
        }
        return cycleCount;
    }

    static long computeTotalSolutions(long p, long k) {
        long cycles;
        if (k == 0) {
            cycles = p - 1;
        } else if (k == 1) {
            cycles = p;
        } else {
            cycles = countCyclesInGraph(p, k);
        }
        long total = 1;
        for (long i = 0; i < cycles; ++i) {
            total = (total * p) % MOD;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        System.out.println(computeTotalSolutions(p, k));
        int dummy = sc.nextInt(); // read dummy input
        sc.close();
    }
}
